/// Application-owned typed HTTP operation.
pub struct FetchItems;
impl crate::http::Operation for FetchItems {
    type Input = ();
    type Output = Vec<String>;
    fn request(input: &Self::Input) -> Result<crate::http::Request, crate::http::Error> {
        let _ = input;
        Ok(crate::http::Request {
            method: crate::http::Method::Get,
            url: "http://127.0.0.1:18788/items".to_owned(),
            query: vec![],
            headers: vec![],
            body: None,
            auth: crate::http::Auth::None,
        })
    }
    fn decode(value: serde_json::Value) -> Result<Option<Self::Output>, crate::http::Error> {
        let value = value.pointer("/items").ok_or(crate::http::Error::Mapping)?.clone();
        if value.is_null() || value.as_array().is_some_and(Vec::is_empty) { return Ok(None); }
        serde_json::from_value(value).map(Some).map_err(|_| crate::http::Error::Decode)
    }
    fn fixture(input: &Self::Input) -> Result<Option<Self::Output>, crate::http::Error> {
        let _ = input;
        Self::decode(serde_json::from_str("{\"items\":[\"Alpha\",\"Beta\"]}").map_err(|_| crate::http::Error::Decode)?)
    }
}

