src/http.rs:
//! Application-owned HTTP execution and request state.
//!
//! ## Wiring
//! Inject Transport and Secrets into Service; choose Fixture explicitly in Design.
//! ViewModels retain Resource and observe its watch receiver. Every Flight owns a
//! unique identity, so replacement, cancellation and task abortion cannot publish
//! a stale result. This module depends on Tokio, reqwest, serde_json and zeroize,
//! never on Trinity or the UI framework.
//!
//! ## Production gotchas
//! Credentials stay in the secret provider and are resolved only for Live calls.
//! Failures deliberately omit response bodies, URLs and transport diagnostics that
//! could echo credentials. Native HTTP disables redirects and bounds response size.

use std::future::Future;
use std::sync::{Arc, Mutex};
use tokio::sync::watch;
use zeroize::Zeroizing;

// =============================================================================
// Ports and request values
// =============================================================================

/// An HTTP method, with no transport-specific representation.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Method {
    /// Retrieve a representation.
    Get,
    /// Submit a new operation.
    Post,
    /// Replace a resource.
    Put,
    /// Partially update a resource.
    Patch,
    /// Remove a resource.
    Delete,
    /// Retrieve response headers.
    Head,
    /// Inspect endpoint capabilities.
    Options,
    /// Establish a tunnel when the endpoint supports it.
    Connect,
    /// Request diagnostic tracing.
    Trace,
}
impl Method {
    /// Wire token.
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Get => "GET",
            Self::Post => "POST",
            Self::Put => "PUT",
            Self::Patch => "PATCH",
            Self::Delete => "DELETE",
            Self::Head => "HEAD",
            Self::Options => "OPTIONS",
            Self::Connect => "CONNECT",
            Self::Trace => "TRACE",
        }
    }
}
/// Public header value or external secret reference.
#[derive(Clone)]
pub enum Value {
    /// Ordinary public value.
    Public(String),
    /// External secret name, resolved only for live execution.
    Secret(String),
}
/// API key placement.
#[derive(Clone, Copy)]
pub enum Location {
    /// Send the key in a named header.
    Header,
    /// Send the key in a named query parameter.
    Query,
}
/// Authentication references, never credentials.
#[derive(Clone)]
pub enum Auth {
    /// No authentication.
    None,
    /// Bearer credential reference.
    Bearer(String),
    /// Username and password references.
    Basic { username: String, password: String },
    /// Named API-key reference and placement.
    ApiKey {
        name: String,
        secret: String,
        location: Location,
    },
}
/// An unresolved application request. Debug intentionally cannot print its values.
pub struct Request {
    /// HTTP method.
    pub method: Method,
    /// URL, without embedded credentials.
    pub url: String,
    /// Ordered query parameters, including repeated names.
    pub query: Vec<(String, String)>,
    /// Ordered header values or secret references.
    pub headers: Vec<(String, Value)>,
    /// Optional JSON body.
    pub body: Option<serde_json::Value>,
    /// Authentication references.
    pub auth: Auth,
}
/// Sanitized execution failure, safe to expose without echoing network content.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Error {
    /// Invalid URL, header or ambiguous authentication.
    Request,
    /// A required credential was unavailable.
    MissingSecret,
    /// Connection, timeout or I/O failed.
    Transport,
    /// The server returned a non-success status.
    Status(u16),
    /// The response exceeded the bounded byte budget.
    ResponseLimit,
    /// JSON or the typed response could not be decoded.
    Decode,
    /// The response did not contain the selected JSON pointer.
    Mapping,
    /// The resource synchronization state was poisoned.
    State,
}
impl std::fmt::Display for Error {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "HTTP operation: {self:?}")
    }
}
impl std::error::Error for Error {}
/// Resolves external credentials only when a Live operation is requested.
pub trait Secrets {
    /// Resolve one credential into transient zeroizing storage.
    fn resolve(&self, reference: &str) -> Result<Zeroizing<String>, Error>;
}
/// Local environment-backed credentials; applications may inject a keychain instead.
pub struct Environment;
impl Secrets for Environment {
    fn resolve(&self, reference: &str) -> Result<Zeroizing<String>, Error> {
        std::env::var(reference)
            .map(Zeroizing::new)
            .map_err(|_| Error::MissingSecret)
    }
}
/// Resolved values are transient and zeroized when the prepared request is dropped.
pub struct Prepared {
    /// Method and URL (URL credentials are rejected by the transport).
    pub method: Method,
    /// Request endpoint.
    pub url: String,
    /// Query parameters; values may contain resolved API keys.
    pub query: Vec<(String, Zeroizing<String>)>,
    /// Public and secret headers share transient sensitive storage.
    pub headers: Vec<(String, Zeroizing<String>)>,
    /// Optional JSON request body.
    pub body: Option<serde_json::Value>,
    /// Basic authentication credentials, when selected.
    pub basic: Option<(Zeroizing<String>, Zeroizing<String>)>,
}
/// A bounded transport response; no diagnostics or credential-bearing URL is retained.
pub struct Response {
    /// HTTP status code.
    pub status: u16,
    /// Raw response bytes within the transport budget.
    pub body: Vec<u8>,
}
/// Injected async HTTP transport. Dropping its future must cancel pending work.
pub trait Transport {
    /// Send transient request values; errors must not echo credentials.
    fn send(&self, request: Prepared) -> impl Future<Output = Result<Response, Error>> + Send;
}
/// Source-owned typed operation, independent of any editor.
pub trait Operation {
    /// Input provided by the ViewModel at invocation.
    type Input;
    /// Typed result, decoded by the operation's ordinary Rust mapping.
    type Output;
    /// Build unresolved request values from input.
    fn request(input: &Self::Input) -> Result<Request, Error>;
    /// Decode and select the typed response, or an explicit empty result.
    fn decode(value: serde_json::Value) -> Result<Option<Self::Output>, Error>;
    /// Design-time result; must not resolve credentials or call a transport.
    fn fixture(input: &Self::Input) -> Result<Option<Self::Output>, Error>;
}
/// An explicit execution choice; Design does not infer a live connection.
#[derive(Clone, Copy)]
pub enum Mode {
    /// Use the operation fixture without network or credentials.
    Fixture,
    /// Resolve credentials and invoke the configured transport.
    Live,
}
/// Injected application service. The host chooses its transport and secret provider.
pub struct Service<T, S> {
    transport: T,
    secrets: S,
}
impl<T: Transport, S: Secrets> Service<T, S> {
    /// Compose the service without doing I/O.
    pub const fn new(transport: T, secrets: S) -> Self {
        Self { transport, secrets }
    }
    /// Run one operation. Cancellation is provided by Resource's Flight wrapper.
    pub async fn execute<O: Operation>(
        &self,
        input: &O::Input,
        mode: Mode,
    ) -> Result<Option<O::Output>, Error> {
        if matches!(mode, Mode::Fixture) {
            return O::fixture(input);
        }
        let request = prepare(O::request(input)?, &self.secrets)?;
        let response = self.transport.send(request).await?;
        if !(200..300).contains(&response.status) {
            return Err(Error::Status(response.status));
        }
        if response.body.len() > MAX_RESPONSE {
            return Err(Error::ResponseLimit);
        }
        if response.status == 204 || response.body.is_empty() {
            return Ok(None);
        }
        O::decode(serde_json::from_slice(&response.body).map_err(|_| Error::Decode)?)
    }
}
fn prepare(request: Request, secrets: &impl Secrets) -> Result<Prepared, Error> {
    let mut prepared = Prepared {
        method: request.method,
        url: request.url,
        query: request
            .query
            .into_iter()
            .map(|(k, v)| (k, Zeroizing::new(v)))
            .collect(),
        headers: Vec::new(),
        body: request.body,
        basic: None,
    };
    for (name, value) in request.headers {
        prepared.headers.push((
            name,
            match value {
                Value::Public(value) => Zeroizing::new(value),
                Value::Secret(reference) => secrets.resolve(&reference)?,
            },
        ));
    }
    let auth_header = match &request.auth {
        Auth::None
        | Auth::ApiKey {
            location: Location::Query,
            ..
        } => None,
        Auth::Bearer(_) | Auth::Basic { .. } => Some("authorization"),
        Auth::ApiKey {
            name,
            location: Location::Header,
            ..
        } => Some(name.as_str()),
    };
    if auth_header.is_some_and(|name| {
        prepared
            .headers
            .iter()
            .any(|(header, _)| header.eq_ignore_ascii_case(name))
    }) {
        return Err(Error::Request);
    }
    match request.auth {
        Auth::None => (),
        Auth::Bearer(reference) => prepared.headers.push((
            "Authorization".into(),
            Zeroizing::new(format!("Bearer {}", secrets.resolve(&reference)?.as_str())),
        )),
        Auth::Basic { username, password } => {
            prepared.basic = Some((secrets.resolve(&username)?, secrets.resolve(&password)?));
        }
        Auth::ApiKey {
            name,
            secret,
            location,
        } => {
            let value = (name, secrets.resolve(&secret)?);
            match location {
                Location::Header => prepared.headers.push(value),
                Location::Query => prepared.query.push(value),
            }
        }
    }
    Ok(prepared)
}

// =============================================================================
// Native transport
// =============================================================================

/// Bounded JSON response budget (four MiB).
pub const MAX_RESPONSE: usize = 4 * 1024 * 1024;
/// Reqwest adapter outside the UI framework, with redirects disabled.
pub struct Http {
    client: reqwest::Client,
}
impl Http {
    /// Build a transport with a thirty-second request timeout.
    pub fn new() -> Result<Self, Error> {
        let client = reqwest::Client::builder()
            .redirect(reqwest::redirect::Policy::none())
            .timeout(std::time::Duration::from_secs(30))
            .build()
            .map_err(|_| Error::Transport)?;
        Ok(Self { client })
    }
}
impl Transport for Http {
    async fn send(&self, request: Prepared) -> Result<Response, Error> {
        let url = reqwest::Url::parse(&request.url).map_err(|_| Error::Request)?;
        if !matches!(url.scheme(), "http" | "https")
            || !url.username().is_empty()
            || url.password().is_some()
        {
            return Err(Error::Request);
        }
        let method = reqwest::Method::from_bytes(request.method.as_str().as_bytes())
            .map_err(|_| Error::Request)?;
        let mut builder = self.client.request(method, url);
        for (name, value) in &request.query {
            builder = builder.query(&[(name, value.as_str())]);
        }
        let mut headers = reqwest::header::HeaderMap::new();
        for (name, value) in &request.headers {
            let name = reqwest::header::HeaderName::from_bytes(name.as_bytes())
                .map_err(|_| Error::Request)?;
            let mut value =
                reqwest::header::HeaderValue::from_str(value).map_err(|_| Error::Request)?;
            value.set_sensitive(true);
            headers.append(name, value);
        }
        builder = builder.headers(headers);
        if let Some((username, password)) = &request.basic {
            builder = builder.basic_auth(username.as_str(), Some(password.as_str()));
        }
        if let Some(body) = &request.body {
            builder = builder.json(body);
        }
        let mut response = builder.send().await.map_err(|_| Error::Transport)?;
        let status = response.status().as_u16();
        if response
            .content_length()
            .is_some_and(|n| n > MAX_RESPONSE as u64)
        {
            return Err(Error::ResponseLimit);
        }
        let mut body = Vec::new();
        while let Some(chunk) = response.chunk().await.map_err(|_| Error::Transport)? {
            if chunk.len() > MAX_RESPONSE.saturating_sub(body.len()) {
                return Err(Error::ResponseLimit);
            }
            body.extend_from_slice(&chunk);
        }
        Ok(Response { status, body })
    }
}

// =============================================================================
// Latest-request resource and observable lifecycle
// =============================================================================

/// Observable state retained by a ViewModel.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Load<T> {
    /// No request has started.
    Idle,
    /// The current request is pending.
    Loading,
    /// The latest request returned typed data.
    Success(T),
    /// The latest request completed without data.
    Empty,
    /// The latest request failed with a sanitized error.
    Error(Error),
    /// The current request was cancelled or its task was aborted.
    Cancelled,
}
struct Active {
    identity: Arc<()>,
    cancel: watch::Sender<bool>,
}
struct Control<T> {
    active: Option<Active>,
    state: watch::Sender<Load<T>>,
}
/// Shared state with per-invocation identity and cancellation.
pub struct Resource<T> {
    control: Arc<Mutex<Control<T>>>,
    receiver: watch::Receiver<Load<T>>,
}
impl<T> Clone for Resource<T> {
    fn clone(&self) -> Self {
        Self {
            control: self.control.clone(),
            receiver: self.receiver.clone(),
        }
    }
}
impl<T: Clone> Default for Resource<T> {
    fn default() -> Self {
        Self::new()
    }
}
impl<T: Clone> Resource<T> {
    /// Create an idle resource; each construction has independent request state.
    pub fn new() -> Self {
        let (state, receiver) = watch::channel(Load::Idle);
        Self {
            control: Arc::new(Mutex::new(Control {
                active: None,
                state,
            })),
            receiver,
        }
    }
    /// Subscribe to lifecycle transitions; UI adapters observe this receiver.
    pub fn subscribe(&self) -> watch::Receiver<Load<T>> {
        self.receiver.clone()
    }
    /// Read the most recent published state.
    pub fn snapshot(&self) -> Load<T> {
        self.receiver.borrow().clone()
    }
    /// Begin one request, cancelling its predecessor before publishing Loading.
    pub fn begin(&self) -> Result<Flight<T>, Error> {
        let mut control = self.control.lock().map_err(|_| Error::State)?;
        if let Some(previous) = control.active.take() {
            previous.cancel.send_replace(true);
        }
        let identity = Arc::new(());
        let (cancel, receiver) = watch::channel(false);
        control.active = Some(Active {
            identity: identity.clone(),
            cancel,
        });
        control.state.send_replace(Load::Loading);
        drop(control);
        Ok(Flight {
            control: self.control.clone(),
            identity,
            cancel: receiver,
            finished: false,
        })
    }
    /// Cancel current work and publish an explicit cancelled state.
    pub fn cancel(&self) -> Result<(), Error> {
        let mut control = self.control.lock().map_err(|_| Error::State)?;
        if let Some(active) = control.active.take() {
            active.cancel.send_replace(true);
            control.state.send_replace(Load::Cancelled);
        }
        drop(control);
        Ok(())
    }
}
/// Whether the captured request was still current when it finished.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Completion {
    /// The current request published its result.
    Applied,
    /// The request was cancelled or superseded.
    Discarded,
}
/// A single in-flight request; dropping it cancels only its own current state.
pub struct Flight<T> {
    control: Arc<Mutex<Control<T>>>,
    identity: Arc<()>,
    cancel: watch::Receiver<bool>,
    finished: bool,
}
impl<T> Flight<T> {
    /// Race execution against cancellation and publish only while identity matches.
    pub async fn run(
        mut self,
        future: impl Future<Output = Result<Option<T>, Error>>,
    ) -> Result<Completion, Error> {
        let result = tokio::select! { biased; _ = self.cancel.wait_for(|cancel| *cancel) => None, value = future => Some(value) };
        let mut control = self.control.lock().map_err(|_| Error::State)?;
        self.finished = true;
        if !control
            .active
            .as_ref()
            .is_some_and(|active| Arc::ptr_eq(&active.identity, &self.identity))
        {
            return Ok(Completion::Discarded);
        }
        control.active = None;
        let Some(result) = result else {
            control.state.send_replace(Load::Cancelled);
            return Ok(Completion::Discarded);
        };
        control.state.send_replace(match result {
            Ok(Some(value)) => Load::Success(value),
            Ok(None) => Load::Empty,
            Err(error) => Load::Error(error),
        });
        drop(control);
        Ok(Completion::Applied)
    }
}
impl<T> Drop for Flight<T> {
    fn drop(&mut self) {
        if self.finished {
            return;
        }
        if let Ok(mut control) = self.control.lock()
            && control
                .active
                .as_ref()
                .is_some_and(|active| Arc::ptr_eq(&active.identity, &self.identity))
        {
            control.active = None;
            control.state.send_replace(Load::Cancelled);
        }
    }
}

