/// A typed record shared by the collection, detail and update operations.
#[derive(Clone, Debug, Default, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct Record {
    /// Stable server identity.
    pub id: u32,
    /// Editable record title.
    pub title: String,
}

/// A collection query or a query for one selected record.
#[derive(Clone)]
pub struct Query {
    /// Local fixture service origin.
    pub base_url: String,
    /// Selected record, or the full collection.
