src/native_http.rs:
//! Application-owned HTTP observation on the native UI thread.
//!
//! ## Wiring
//! ViewModels retain Request and inject Service plus an explicit execution context.
//! UI state is never sent across threads. Dropping the last request owner cancels
//! its observer and background work; a copied State handle does not own the request.
use crate::http::{Error, Load, Mode, Operation, Resource, Secrets, Service, Transport};
use bunny_ui::prelude::State;
use std::{cell::RefCell, future::Future, pin::Pin, rc::Rc, sync::Arc};

/// The caller chooses fixture execution or supplies its native async executor.
#[derive(Clone)]
pub enum Execution {
    /// No transport, credential resolution or async runtime is needed.
    Fixture,
    /// Use the injected service on this application-owned executor.
    Live(tokio::runtime::Handle),
}
struct Work {
    worker: Option<tokio::task::AbortHandle>,
    _observer: bunny_ui::task::Spawned,
}
impl Drop for Work {
    fn drop(&mut self) {
        if let Some(worker) = &self.worker {
            worker.abort();
        }
        // The observer's Drop cancels its UI future before another UI turn runs.
    }
}
type Observer<T> = Rc<dyn Fn(Load<T>)>;
struct Projection<T: Clone + 'static> {
    state: State<Load<T>>,
    callback: RefCell<Option<Observer<T>>>,
}
impl<T: Clone + 'static> Projection<T> {
    fn publish(&self, value: Load<T>) {
        self.state.set(value.clone());
        let callback = self.callback.borrow().clone();
        if let Some(callback) = callback {
            callback(value);
        }
    }
}

#[derive(Clone, Copy)]
enum Disposal {
    Publish,
    Silent,
}
struct Owner<T: Clone + 'static> {
    source: Resource<T>,
    projection: Rc<Projection<T>>,
    work: RefCell<Option<Work>>,

identity: RefCell<Rc<()>>,
    disposal: std::cell::Cell<Disposal>,
}
impl<T: Clone + 'static> Drop for Owner<T> {
    fn drop(&mut self) {
        self.work.get_mut().take();

if matches!(self.disposal.get(), Disposal::Publish) {
match self.source.cancel() {
            Ok(()) => self.projection.publish(self.source.snapshot()),
            Err(error) => self.projection.publish(Load::Error(error)),
        }
    }
}

}
/// A cloned handle shares one ViewModel request; constructing another is independent.
#[derive(Clone)]
pub struct Request<T: Clone + 'static> {
    owner: Rc<Owner<T>>,
}
impl<T: Clone + 'static> Default for Request<T> {
    fn default() -> Self {
        Self::new()
    }
}
impl<T: Clone + 'static> Request<T> {
    /// Construct idle native state, without allocating a thread or opening a connection.
    pub fn new() -> Self {
        Self {
            owner: Rc::new(Owner {
                source: Resource::new(),
                projection: Rc::new(Projection {
                    state: State::new(Load::Idle),
                    callback: RefCell::new(None),
                }),
                work: RefCell::new(None),

identity: RefCell::new(Rc::new(())),
                disposal: std::cell::Cell::new(Disposal::Publish),
}),
        }
    }
    /// Reactive state for the ViewModel or view. This handle alone owns no async work.
    pub fn state(&self) -> State<Load<T>> {
        self.owner.projection.state
    }
    /// Cancel current work; a completed result remains completed.
    pub fn cancel(&self) -> Result<(), Error> {
        self.owner.
identity.replace(Rc::new(()));
        self.owner.
work.borrow_mut().take();
        self.owner.source.cancel()?;
        self.owner.projection.publish(self.owner.source.snapshot());
        Ok(())
    }
}
impl<T: Clone + Send + Sync + 'static> Request<T> {
    /// Start the typed operation and replace prior work without stale UI delivery.
    ///
    /// The background executor and Service are supplied by the application. The
    /// UI observer reads the same guarded Resource and owns no ViewModel reference.
    pub fn execute<O, P, S>(
        &self,
        service: Arc<Service<P, S>>,
        input: O::Input,
        execution: Execution,
    ) -> Result<(), Error>
    where
        O: Operation<Output = T> + 'static,
        O::Input: Send + Sync + 'static,
        P: Transport + Send + Sync + 'static,
        S: Secrets + Send + Sync + 'static,
    {
        match execution {
            Execution::Fixture => self.start(async move { O::fixture(&input) }, None),
            Execution::Live(executor) => self.start(
                async move { service.as_ref().execute::<O>(&input, Mode::Live).await },
                Some(executor),
            ),
        }
    }
    fn start(
        &self,
        future: impl Future<Output = Result<Option<T>, Error>> + Send + 'static,
        executor: Option<tokio::runtime::Handle>,
    ) -> Result<(), Error> {

let identity = Rc::new(());
self.owner.
identity.replace(identity.clone());
        self.owner.
work.borrow_mut().take();
        let flight = self.owner.source.begin()?;
        let projection = self.owner.projection.clone();
        projection.publish(Load::Loading);

if !Rc::ptr_eq(&identity, &self.owner.identity.borrow()) {
            return Ok(());
        }
let source = self.owner.source.clone();
        let work = match executor {
            None => {
                let observer = bunny_ui::task::spawn(async move {
                    if let Err(error) = flight.run(future).await {
                        projection.publish(Load::Error(error));
                    } else {
                        projection.publish(source.snapshot());
                    }
                });
                Work {
                    worker: None,
                    _observer: observer,
                }
            }
            Some(executor) => {
                let worker = executor.spawn(async move { flight.run(future).await });
                let abort = worker.abort_handle();
                let observer = bunny_ui::task::spawn(async move {
                    let next = match worker.await {
                        Ok(Ok(_)) => source.snapshot(),
                        Ok(Err(error)) => Load::Error(error),
                        Err(error) if error.is_cancelled() => Load::Cancelled,
                        Err(_) => Load::Error(Error::State),
                    };
                    projection.publish(next);
                });
                Work {
                    worker: Some(abort),
                    _observer: observer,
                }
            }
        };
        self.owner.work.replace(Some(work));
        Ok(())
    }
}

// =============================================================================
// Typed ViewModel storage at the native UI boundary
// =============================================================================

type Response<T> = Pin<Box<dyn Future<Output = Result<Option<T>, Error>> + Send>>;
trait Execute<O: Operation>: Send + Sync {
    fn execute(self: Arc<Self>, input: O::Input) -> Response<O::Output>;
}
impl<O, P, S> Execute<O> for Service<P, S>
where
    O: Operation + 'static,
    O::Input: Send + Sync + 'static,
    O::Output: Send + 'static,
    P: Transport + Send + Sync + 'static,
    S: Secrets + Send + Sync + 'static,
{
    fn execute(self: Arc<Self>, input: O::Input) -> Response<O::Output> {
        Box::pin(async move { self.as_ref().execute::<O>(&input, Mode::Live).await })
    }
}
/// Typed operation client. Only the native storage boundary erases injected ports.
pub struct Client<O: Operation> {
    service: Arc<dyn Execute<O>>,
}
impl<O: Operation> Clone for Client<O> {
    fn clone(&self) -> Self {
        Self {
            service: self.service.clone(),
        }
    }
}
impl<O: Operation + 'static> Client<O>
where
    O::Input: Send + Sync + 'static,
    O::Output: Send + 'static,
{
    /// Retain an application-owned service without requiring a generic ViewModel.
    pub fn new<P, S>(service: Arc<Service<P, S>>) -> Self
    where
        P: Transport + Send + Sync + 'static,
        S: Secrets + Send + Sync + 'static,
    {
        Self { service }
    }
}
/// Live execution cannot exist without both a service and its executor.
pub enum Context<O: Operation> {
    /// Design fixtures need neither credentials nor a runtime.
    Fixture,
    /// Application-owned connection and executor.
    Live {
        client: Client<O>,
        executor: tokio::runtime::Handle,
    },
}
impl<O: Operation> Clone for Context<O> {
    fn clone(&self) -> Self {
        match self {
            Self::Fixture => Self::Fixture,
            Self::Live { client, executor } => Self::Live {
                client: client.clone(),
                executor: executor.clone(),
            },
        }
    }
}
/// One ViewModel's cancellable operation and explicit execution context.
///
/// Projection callbacks must capture State handles, never the owning ViewModel.
/// Clones share a lifetime; distinct constructors allocate independent requests.
pub struct Connection<O: Operation>
where
    O::Output: Clone + 'static,
{
    request: Request<O::Output>,
    context: Rc<RefCell<Context<O>>>,

execution: Option<Rc<ExecutionBinding>>,
    configured: Rc<std::cell::Cell<bool>>,
}
impl<O: Operation> Clone for Connection<O>
where
    O::Output: Clone + 'static,
{
    fn clone(&self) -> Self {
        Self {
            request: self.request.clone(),
            context: self.context.clone(),

execution: self.execution.clone(),
            configured: self.configured.clone(),
}
    }
}
impl<O: Operation + 'static> Default for Connection<O>
where
    O::Input: Send + Sync + 'static,
    O::Output: Clone + Send + Sync + 'static,
{
    fn default() -> Self {
        Self::new()
    }
}
impl<O: Operation + 'static> Connection<O>
where
    O::Input: Send + Sync + 'static,
    O::Output: Clone + Send + Sync + 'static,
{
    /// Start idle in fixture mode. No ports are constructed or contacted.
    pub fn new() -> Self {
        Self {
            request: Request::new(),
            context: Rc::new(RefCell::new(Context::Fixture)),

execution: None,
            configured: Rc::new(std::cell::Cell::new(false)),
}
    }
    /// Observe this request without retaining its lifetime.
    pub fn state(&self) -> State<Load<O::Output>> {
        self.request.state()
    }
    /// Cancel old work before replacing the application-owned execution context.
    pub fn configure(&self, context: Context<O>) {
        self.
configured.set(true);
        self.
cancel();
        self.context.replace(context);
    }
    /// Cancel current work and deliver any cancellation failure to the projection.
    pub fn cancel(&self) {
        if let Err(error) = self.request.cancel() {
            self.request.owner.projection.publish(Load::Error(error));
        }
    }
    /// Execute and project every state transition on the UI thread.
    pub fn load(&self, input: O::Input, project: impl Fn(Load<O::Output>) + 'static) {
        self.request
            .owner
            .projection
            .callback
            .replace(Some(Rc::new(project)));
        let context = self.context.borrow().clone();
        let 
context = match self.resolve(context) {
            Ok(Some(context)) => context,
            Ok(None) => {
                self.request.owner.projection.publish(Load::Cancelled);
                return;
            }
            Err(error) => {
                self.request.owner.projection.publish(Load::Error(error));
                return;
            }
        };
        let
result = match context {
            Context::Fixture => self.request.start(async move { O::fixture(&input) }, None),
            Context::Live { client, executor } => self
                .request
                .start(client.service.execute(input), Some(executor)),
        };
        if let Err(error) = result {
            self.request.owner.projection.publish(Load::Error(error));
        }
    }
}


// =============================================================================
// Application execution follows the captured scene, never the ambient UI poller
// =============================================================================

struct ExecutionBinding {
    context: Option<bunny_ui::preview::ExecutionContext>,
    _subscription: Option<bunny_ui::preview::ExecutionSubscription>,
}
impl ExecutionBinding {
    fn mode(&self) -> Option<bunny_ui::preview::ExecutionMode> {
        self.context.as_ref().map_or(
            Some(bunny_ui::preview::ExecutionMode::Play),
            bunny_ui::preview::ExecutionContext::mode,
        )
    }
}
impl<O: Operation + 'static> Connection<O>
where
    O::Input: Send + Sync + 'static,
    O::Output: Clone + Send + Sync + 'static,
{
    /// Follow the constructing preview's Design/Play mode and closure.
    ///
    /// Outside a preview this is a standalone live application. Design always uses
    /// fixtures, including when a live service is injected. Play uses the configured
    /// context, or lazily creates application-owned HTTP/environment ports and an
    /// executor. Mode changes cancel current work; inputs are never silently replayed.
    /// A closed scene refuses subsequent loads even when this connection is retained.
    pub fn application() -> Self {
        let mut connection = Self::new();
        let context = bunny_ui::preview::ExecutionContext::current();
        let request = connection.request.clone();
        let subscription = context.as_ref().map(|context| {
            let observed = context.clone();
            context.subscribe(move |_| {
                if observed.mode().is_none() {
                    request.owner.disposal.set(Disposal::Silent);
                }
                if let Err(error) = request.invalidate() {
                    request.owner.projection.publish(Load::Error(error));
                }
            })
        });
        connection.execution = Some(Rc::new(ExecutionBinding {
            context,
            _subscription: subscription,
        }));
        connection
    }
    fn resolve(&self, context: Context<O>) -> Result<Option<Context<O>>, Error> {
        use bunny_ui::preview::ExecutionMode;
        let Some(binding) = &self.execution else {
            return Ok(Some(context));
        };
        match binding.mode() {
            None => Ok(None),
            Some(ExecutionMode::Design) => Ok(Some(Context::Fixture)),
            Some(ExecutionMode::Play) if self.configured.get() => Ok(Some(context)),
            Some(ExecutionMode::Play) => {
                let executor = application_executor()?;
                let client = Client::new(Arc::new(Service::new(
                    crate::http::Http::new()?,
                    crate::http::Environment,
                )));
                let context = Context::Live { client, executor };
                self.context.replace(context.clone());
                self.configured.set(true);
                Ok(Some(context))
            }
        }
    }
}
fn application_executor() -> Result<tokio::runtime::Handle, Error> {
    // A static application-owned executor is never dropped on a UI/async thread.
    // Runtime construction and credential resolution are absent from Design.
    static EXECUTOR: std::sync::OnceLock<Result<tokio::runtime::Runtime, Error>> =
        std::sync::OnceLock::new();
    EXECUTOR
        .get_or_init(|| {
            tokio::runtime::Builder::new_multi_thread()
                .worker_threads(2)
                .enable_all()
                .build()
                .map_err(|_| Error::Transport)
        })
        .as_ref()
        .map(|runtime| runtime.handle().clone())
        .map_err(Clone::clone)
}

impl<T: Clone + 'static> Request<T> {
    fn invalidate(&self) -> Result<(), Error> {
        use bunny_ui::prelude::StateExt as _;
        self.owner.identity.replace(Rc::new(()));
        self.owner.work.borrow_mut().take();
        self.owner.source.cancel()?;
        // A terminal background value queued for UI delivery belongs to the old
        // execution mode. Keep values already observed, never publish that queue.
        if matches!(self.state().get(), Load::Loading) {
            self.owner.projection.publish(Load::Cancelled);
        }
        Ok(())
    }
}

