use bunny_ui::prelude::*;

/// Application destinations with typed parameters.
#[derive(Clone, Debug, PartialEq)]
pub enum NativeRecordsAppRoute {
    /// The Detail screen and its typed payload.
    Detail { /// Route parameter.
id: u32 },
    /// The Edit screen and its typed payload.
    Edit { /// Route parameter.
id: u32, /// Route parameter.
title: String },
    /// The List screen.
    List,
}

/// One atomic navigation snapshot.
#[derive(Clone, Debug, PartialEq)]
pub struct NativeRecordsAppNavigationState {
    /// Mounted destination.
    pub current: NativeRecordsAppRoute,
    /// Earlier destinations, oldest first.
    pub history: std::vec::Vec<NativeRecordsAppRoute>,
    /// Optional destination presented above the current screen.
    pub modal: std::option::Option<NativeRecordsAppRoute>,
}

/// Shared navigation commands for one application instance.
#[derive(Clone)]
pub struct NativeRecordsAppNavigation {
    /// Current route, history and modal change together.
    pub state: bunny_ui::prelude::State<NativeRecordsAppNavigationState>,
}
impl NativeRecordsAppNavigation {
    /// Start a fresh history at the supplied destination.
    pub fn new(initial: NativeRecordsAppRoute) -> Self {
        Self { state: bunny_ui::prelude::State::new(NativeRecordsAppNavigationState { current: initial, history: std::vec::Vec::new(), modal: std::option::Option::None }) }
    }
    /// Push the current route, mount the destination and dismiss any modal.
    pub fn open(&self, route: NativeRecordsAppRoute) {
        self.state.update(|state| {
            state.history.push(state.current.clone());
            state.current = route;
            state.modal = std::option::Option::None;
        });
    }
    /// Mount the previous destination, or remain at the history root.
    pub fn back(&self) {
        self.state.update(|state| {
            if let std::option::Option::Some(route) = state.history.pop() {
                state.current = route;
                state.modal = std::option::Option::None;
            }
        });
    }
    /// Present a modal destination without modifying history.
    pub fn present(&self, route: NativeRecordsAppRoute) {
        self.state.update(|state| state.modal = std::option::Option::Some(route));
    }
    /// Close the current modal.
    pub fn dismiss(&self) {
        self.state.update(|state| state.modal = std::option::Option::None);
    }
    /// Connect native sheet dismissal to the navigation snapshot.
    pub fn modal_presented(&self) -> bunny_ui::prelude::Binding<bool> {
        let read = self.clone();
        let write = self.clone();
        bunny_ui::prelude::Binding::new(move || read.state.get().modal.is_some(), move |shown| {
            if !shown { write.dismiss(); }
        })
    }
}

/// Mounts actual screens and owns their retained application state.
#[derive(Clone)]
pub struct NativeRecordsApp {
    /// Navigation shared with the mounted screens.
    pub navigation: NativeRecordsAppNavigation,
    /// State retained across route mounts.
    pub(crate) screen_0_vm: crate::native_record_detail_vm::NativeRecordDetailViewModel,
    /// State retained across route mounts.
    pub(crate) screen_1_vm: crate::native_record_edit_vm::NativeRecordEditViewModel,
    /// State retained across route mounts.
    pub(crate) screen_2_vm: crate::native_state_probe_vm::NativeStateProbeViewModel,
}
impl std::default::Default for NativeRecordsApp {
    fn default() -> Self {
        let navigation = NativeRecordsAppNavigation::new(NativeRecordsAppRoute::List);
        let screen_0_vm = std::default::Default::default();
        let screen_1_vm = std::default::Default::default();
        let screen_2_vm = std::default::Default::default();
        Self { navigation, screen_0_vm, screen_1_vm, screen_2_vm }
    }
}
impl NativeRecordsApp {
    fn mount(&self, route: NativeRecordsAppRoute) -> bunny_ui::prelude::Erased {
        let identity = format!("{route:?}");
        let content = match route {
            NativeRecordsAppRoute::Detail { id } => bunny_ui::erased::erased(crate::native_record_detail::NativeRecordDetail { navigation: self.navigation.clone(), id, vm: self.screen_0_vm.clone() }),
            NativeRecordsAppRoute::Edit { id, title } => bunny_ui::erased::erased(crate::native_record_edit::NativeRecordEdit { navigation: self.navigation.clone(), id, title, vm: self.screen_1_vm.clone() }),
            NativeRecordsAppRoute::List => bunny_ui::erased::erased(crate::native_state_probe::NativeStateProbe { navigation: self.navigation.clone(), vm: self.screen_2_vm.clone() }),
        };
        bunny_ui::erased::erased(content.id(identity))
    }
}
impl bunny_ui::prelude::Component for NativeRecordsApp {
    fn body(self) -> impl bunny_ui::prelude::View {
        let modal = self.clone();
        self.mount(self.navigation.state.get().current).sheet(self.navigation.modal_presented(), move |_| {
            match modal.navigation.state.get().modal {
                std::option::Option::Some(route) => modal.mount(route),
                std::option::Option::None => bunny_ui::erased::erased(bunny_ui::prelude::spacer()),
            }
        })
    }
}

/// The composed application.
pub fn application_root() -> impl bunny_ui::prelude::View { NativeRecordsApp::default() }

/// A fresh application instance.
#[bunny_ui::preview]
fn application_preview() -> impl bunny_ui::prelude::View { application_root() }

